/**
 * Types + lazy loader for licenses.json (generated by scripts/gen-licenses.mjs — `npm run licenses`).
 * The JSON is ~110 KB, so it is only required when the Licences screen first needs it.
 */
export type LicenseGroupId = 'fonts' | 'icons' | 'libraries';

export type LicenseItem = {
  /** Stable, unique: "font:inter", "npm:react", "android:androidx"… */
  id: string;
  name: string;
  /** "" when not versioned (fonts, curated Android entries); "1.0.0, 2.0.0" for several copies. */
  version: string;
  /** SPDX id where there is one ("MIT", "OFL-1.1"), otherwise a short name. */
  license: string;
  copyright: string;
  url: string;
  /** Key into `texts` (identical texts are stored once). */
  textId: string;
};

export type LicenseGroup = { id: LicenseGroupId; items: LicenseItem[] };

export type LicensesFile = { version: 1; groups: LicenseGroup[]; texts: Record<string, string> };

let cache: LicensesFile | null = null;

export function loadLicenses(): LicensesFile {
  if (!cache) cache = require('./licenses.json') as LicensesFile;
  return cache;
}
